function parseLedger(markdown) {
  // The archive contains a decoy heading: "## Transaction Ledger (working copy)".
  // The authoritative ledger heading line is exactly: "## Transaction Ledger".
  const m = markdown.match(/^## Transaction Ledger\s*$/m);
  if (!m) return [];

  const after = markdown.slice(m.index + m[0].length);
  const nextHeading = after.search(/^##\s+/m);
  const section = nextHeading === -1 ? after : after.slice(0, nextHeading);

  const items = [];
  const blocks = section
    .split(/\n(?=###\s+TXN-)/g)
    .map((b) => b.trim())
    .filter((b) => b.startsWith("### TXN-"));

  for (const block of blocks) {
    const lines = block.split(/\r?\n/);
    const transaction_id = lines[0].replace(/^###\s+/, "").trim();
    const entry = { transaction_id, amount: null, owner: null, status: null, date: null, provisional: false };

    for (const line of lines.slice(1)) {
      const trimmed = line.trim();
      if (trimmed.startsWith("amount:")) entry.amount = trimmed.split(":", 2)[1].trim();
      else if (trimmed.startsWith("owner:")) entry.owner = trimmed.split(":", 2)[1].trim();
      else if (trimmed.startsWith("status:")) entry.status = trimmed.split(":", 2)[1].trim();
      else if (trimmed.startsWith("date:")) entry.date = trimmed.split(":", 2)[1].trim();
      else if (trimmed.startsWith("provisional:")) entry.provisional = trimmed.split(":", 2)[1].trim() === 'true';
    }

    if (entry.transaction_id && entry.amount && entry.owner && entry.status && entry.date) items.push(entry);
  }

  return items;
}

module.exports = { parseLedger };
EOF
