function parseEmails(markdown) {
  // Extract only the authoritative "## Email Excerpts" section.
  const m = markdown.match(/^## Email Excerpts\s*$/m);
  if (!m) return [];

  const after = markdown.slice(m.index + m[0].length);
  const nextHeading = after.search(/^##\s+/m);
  const section = nextHeading === -1 ? after : after.slice(0, nextHeading);

  const emails = [];
  const blocks = section.split(/\n\n+/);

  for (const block of blocks) {
    const subjectMatch = block.match(/^Subject:\s*Re:\s*(TXN-[0-9a-f-]+)\s*$/im);
    const sentMatch = block.match(/^sent:\s*(\d{4}-\d{2}-\d{2})\s*$/im);
    const statusMatch = block.match(/^status:\s*(\w+)\s*$/im);
    const fromMatch = block.match(/^From:\s*(.+)\s*$/im);

    if (!subjectMatch || !sentMatch || !statusMatch || !fromMatch) continue;

    emails.push({
      from_addr: fromMatch[1].trim(),
      transaction_id: subjectMatch[1].trim(),
      sent: sentMatch[1].trim(),
      status: statusMatch[1].trim().toLowerCase(),
    });
  }

  return emails;
}

module.exports = { parseEmails };
